<?php
namespace Wortek\Store\Controllers;
use Wortek\Store\Http\Response; use Wortek\Store\Repositories\OrderRepository;
final class OrderController { public function __construct(private OrderRepository $r){} public function index(): never{Response::success(['pedidos'=>$this->r->all()]);} public function show(int $id): never{$x=$this->r->find($id);if(!$x)Response::error('Pedido não encontrado.',404);Response::success(['pedido'=>$x]);} public function store(int $uid): never{$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||empty($d['cliente_id'])||empty($d['itens'])||!is_array($d['itens']))Response::error('Cliente e itens são obrigatórios.',422);foreach($d['itens'] as $it)if(empty($it['descricao'])||!isset($it['quantidade'],$it['preco_unitario']))Response::error('Itens inválidos.',422);$id=$this->r->create($d,$d['itens'],$uid);Response::success(['message'=>'Pedido criado com sucesso.','pedido'=>$this->r->find($id)],201);} public function status(int $id): never{$d=json_decode(file_get_contents('php://input'),true);$e=$d['estado']??'';$allowed=['rascunho','confirmado','em_preparacao','em_entrega','concluido','cancelado'];if(!in_array($e,$allowed,true))Response::error('Estado inválido.',422);if(!$this->r->find($id))Response::error('Pedido não encontrado.',404);$this->r->updateStatus($id,$e);Response::success(['message'=>'Estado actualizado.','pedido'=>$this->r->find($id)]);} }
